import{_ as e,c as a,o as t,a4 as s}from"./chunks/framework.P4k6vdAm.js";const m=JSON.parse('{"title":"Endpoint Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"docs/tasks/index.md","filePath":"docs/tasks/index.md","lastUpdated":1793099931000}'),o={name:"docs/tasks/index.md"},r=s('<h1 id="endpoint-tasks" tabindex="-1">Endpoint Tasks <a class="header-anchor" href="#endpoint-tasks" aria-label="Permalink to &quot;Endpoint Tasks&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Tasks are the bread and butter of AireGlu Endpoints. There are a number of included Tasks you can use, or you can write your own <a href="/docs/developers/adapters.html">adapters</a> to create custom tasks.</p><h3 id="http-request" tabindex="-1"><a href="/docs/tasks/http-request.html">HTTP Request</a> <a class="header-anchor" href="#http-request" aria-label="Permalink to &quot;[HTTP Request](/docs/tasks/http-request)&quot;">​</a></h3><p>The HTTP Request task is used to communicate with external services. You can use this to send data to your APIs, or fetch data from other sources.</p><h3 id="http-response-handler" tabindex="-1"><a href="/docs/tasks/http-response-handler.html">HTTP Response Handler</a> <a class="header-anchor" href="#http-response-handler" aria-label="Permalink to &quot;[HTTP Response Handler](/docs/tasks/http-response-handler)&quot;">​</a></h3><p>The Response Handler can only be used when linked to an HTTP Request. This handles what is returned from the request (e.g. the data from your API). You don&#39;t have to include this if you don&#39;t care about the result of your request, but more often than not the two come as a pair.</p><h3 id="aireglu-endpoint-request" tabindex="-1"><a href="/docs/tasks/aireglu-endpoint-request.html">AireGlu Endpoint Request</a> <a class="header-anchor" href="#aireglu-endpoint-request" aria-label="Permalink to &quot;[AireGlu Endpoint Request](/docs/tasks/aireglu-endpoint-request)&quot;">​</a></h3><p>The AireGlu Endpoint Request task calls another of your endpoints, without needing to configure a full HTTP Request.</p><h3 id="mesh-message" tabindex="-1"><a href="/docs/tasks/mesh-message.html">MESH Message</a> <a class="header-anchor" href="#mesh-message" aria-label="Permalink to &quot;[MESH Message](/docs/tasks/mesh-message)&quot;">​</a></h3><p>The MESH Message task lets you create and send mail via the MESH workflow system.</p><h3 id="email" tabindex="-1"><a href="/docs/tasks/email.html">Email</a> <a class="header-anchor" href="#email" aria-label="Permalink to &quot;[Email](/docs/tasks/email)&quot;">​</a></h3><p>The Email task allows you to send an email. This can be sent from your own email servers, or from AireGlu&#39;s default email server.</p><h3 id="sms" tabindex="-1"><a href="/docs/tasks/sms.html">SMS</a> <a class="header-anchor" href="#sms" aria-label="Permalink to &quot;[SMS](/docs/tasks/sms)&quot;">​</a></h3><p>The SMS task allows you to send text messages using either the MessageBird or GOV.UK notify services</p><h3 id="job" tabindex="-1"><a href="/docs/tasks/job.html">Job</a> <a class="header-anchor" href="#job" aria-label="Permalink to &quot;[Job](/docs/tasks/job)&quot;">​</a></h3><p>The Job task allows an endpoint to be run at a specified time or interval, much like a scheduled task or cron job.</p><h3 id="fax" tabindex="-1"><a href="/docs/tasks/fax.html">Fax</a> <a class="header-anchor" href="#fax" aria-label="Permalink to &quot;[Fax](/docs/tasks/fax)&quot;">​</a></h3><p>The Fax task allows you to send a message or PDF to a Fax machine. A PDF is required and can be part of your input data.</p><h3 id="sftp" tabindex="-1"><a href="/docs/tasks/sftp.html">SFTP</a> <a class="header-anchor" href="#sftp" aria-label="Permalink to &quot;[SFTP](/docs/tasks/sftp)&quot;">​</a></h3><p>The SFTP task lets you securely transfer files to and from remote servers using the SSH File Transfer Protocol.</p><h3 id="http-response" tabindex="-1"><a href="/docs/tasks/http-response.html">HTTP Response</a> <a class="header-anchor" href="#http-response" aria-label="Permalink to &quot;[HTTP Response](/docs/tasks/http-response)&quot;">​</a></h3><p>Lets you specify an HTTP response that the Endpoint should return as its result.</p><h3 id="http-redirect" tabindex="-1"><a href="/docs/tasks/http-redirect.html">HTTP Redirect</a> <a class="header-anchor" href="#http-redirect" aria-label="Permalink to &quot;[HTTP Redirect](/docs/tasks/http-redirect)&quot;">​</a></h3><p>Lets you specify a redirection that should occur as the result of the Endpoint. Useful for sending the user to a &quot;Thank you&quot; page for instance.</p><h3 id="mapping" tabindex="-1"><a href="/docs/tasks/mapping.html">Mapping</a> <a class="header-anchor" href="#mapping" aria-label="Permalink to &quot;[Mapping](/docs/tasks/mapping)&quot;">​</a></h3><p>The Mapping task is for data transformation. It can be used to reformat the data, or modify it in the pipeline. The output of this can be used in any subsequent tasks.</p><h3 id="pdf" tabindex="-1"><a href="/docs/tasks/pdf.html">PDF</a> <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;[PDF](/docs/tasks/pdf)&quot;">​</a></h3><p>The PDF task lets you return a PDF document as the result of the Endpoint.</p><h3 id="jwt" tabindex="-1"><a href="/docs/tasks/jwt.html">JWT</a> <a class="header-anchor" href="#jwt" aria-label="Permalink to &quot;[JWT](/docs/tasks/jwt)&quot;">​</a></h3><p>The JWT task allows you to generate a JWT with customisable headers &amp; payload, with a choice of encryption and/or signing algorithms.</p><h3 id="audit" tabindex="-1"><a href="/docs/tasks/audit.html">Audit</a> <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;[Audit](/docs/tasks/audit)&quot;">​</a></h3><p>The Audit task generates logs and sends them to AireAudit. To view these logs you can navigate to <a href="https://suite.aireinnovate.com/audit" target="_blank" rel="noreferrer">AireAudit</a>. Here you’ll be prompted to sign in, and once logged in, you’ll see a list of audit logs which you can apply filters on.</p><h2 id="configuring-tasks" tabindex="-1">Configuring tasks <a class="header-anchor" href="#configuring-tasks" aria-label="Permalink to &quot;Configuring tasks&quot;">​</a></h2><p>Most task settings can use values from the endpoint input, earlier task results, variables, secrets and built-in functions. See <a href="/docs/building/working-with-data.html">Working with Data</a> for how to use the Context Data panel, the task preview and filters.</p>',35),n=[r];function i(h,d,l,u,c,p){return t(),a("div",null,n)}const k=e(o,[["render",i]]);export{m as __pageData,k as default};
